function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H/2);
  ctx.lineTo(W, H/2);
  ctx.stroke();
  for (let i = 0; i < 5; i++) {
    ctx.save();
    ctx.translate(100 + i * 150, H/2 + Math.sin(t + i) * 20);
    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.fillStyle = 'black';
    ctx.fill();
    ctx.restore();
  }
  ctx.beginPath();
  ctx.rect(50, 50, 20, H - 100);
  ctx.rect(W - 70, 50, 20, H - 100);
  ctx.stroke();
  ctx.restore();
}
